     6  // jvp_utf8_backtrack returns the beginning of the last codepoint in the
     7  // string, assuming that start is the last byte in the string.
     8  // If the last codepoint is incomplete, returns the number of missing bytes via
     9  // *missing_bytes.  If there are no leading bytes or an invalid byte is
    10  // encountered, NULL is returned and *missing_bytes is not altered.
    11  const char* jvp_utf8_backtrack(const char* start, const char* min, int *missing_bytes) {
    12    assert(min <= start);
    13    if (min == start) {
    14      return min;
    15    }
    16    int length = 0;
    17    int seen = 1;
    18    while (start >= min && (length = utf8_coding_length[(unsigned char)*start]) == UTF8_CONTINUATION_BYTE) {
    19      start--;
    20      seen++;
    21    }
    22    if (length == 0 || length == UTF8_CONTINUATION_BYTE || length - seen < 0) {
    23      return NULL;
    24    }
    25    if (missing_bytes) *missing_bytes = length - seen;
    26    return start;
    27  }
