    29  const char* jvp_utf8_next(const char* in, const char* end, int* codepoint_ret) {
    30    assert(in <= end);
    31    if (in == end) {
    32      return 0;
    33    }
    34    int codepoint = -1;
    35    unsigned char first = (unsigned char)in[0];
    36    int length = utf8_coding_length[first];
    37    if ((first & 0x80) == 0) {
    38      /* Fast-path for ASCII */
    39      codepoint = first;
    40      length = 1;
    41    } else if (length == 0 || length == UTF8_CONTINUATION_BYTE) {
    42      /* Bad single byte - either an invalid byte or an out-of-place continuation byte */
    43      length = 1;
    44    } else if (in + length > end) {
    45      /* String ends before UTF8 sequence ends */
    46      length = end - in;
    47    } else {
    48      codepoint = ((unsigned)in[0]) & utf8_coding_bits[first];
    49      for (int i=1; i<length; i++) {
    50        unsigned ch = (unsigned char)in[i];
    51        if (utf8_coding_length[ch] != UTF8_CONTINUATION_BYTE){
    52          /* Invalid UTF8 sequence - not followed by the right number of continuation bytes */
    53          codepoint = -1;
    54          length = i;
    55          break;
    56        }
    57        codepoint = (codepoint << 6) | (ch & 0x3f);
    58      }
    59      if (codepoint < utf8_first_codepoint[length]) {
    60        /* Overlong UTF8 sequence */
    61        codepoint = -1;
    62      }
    63      if (0xD800 <= codepoint && codepoint <= 0xDFFF) {
    64        /* Surrogate codepoints can't be encoded in UTF8 */
    65        codepoint = -1;
    66      }
    67      if (codepoint > 0x10FFFF) {
    68        /* Outside Unicode range */
    69        codepoint = -1;
    70      }
    71    }
    72    assert(length > 0);
    73    *codepoint_ret = codepoint;
    74    return in + length;
    75  }
