   100  int jvp_utf8_encode(int codepoint, char* out) {
   101    assert(codepoint >= 0 && codepoint <= 0x10FFFF);
   102    char* start = out;
   103    if (codepoint <= 0x7F) {
   104      *out++ = codepoint;
   105    } else if (codepoint <= 0x7FF) {
   106      *out++ = 0xC0 + ((codepoint & 0x7C0) >> 6);
   107      *out++ = 0x80 + ((codepoint & 0x03F));
   108    } else if(codepoint <= 0xFFFF) {
   109      *out++ = 0xE0 + ((codepoint & 0xF000) >> 12);
   110      *out++ = 0x80 + ((codepoint & 0x0FC0) >> 6);
   111      *out++ = 0x80 + ((codepoint & 0x003F));
   112    } else {
   113      *out++ = 0xF0 + ((codepoint & 0x1C0000) >> 18);
   114      *out++ = 0x80 + ((codepoint & 0x03F000) >> 12);
   115      *out++ = 0x80 + ((codepoint & 0x000FC0) >> 6);
   116      *out++ = 0x80 + ((codepoint & 0x00003F));
   117    }
   118    assert(out - start == jvp_utf8_encode_length(codepoint));
   119    return out - start;
   120  }
